           <input id="fullName" name="fullName" type="text" autocomplete="name" required aria-required="true" aria-describedby="fullName-error">
           <div id="fullName-error" class="error-message" aria-live="polite" aria-atomic="true"></div>
         </div>

         <div class="form-field" data-field="email">
           <label for="email">Email address <span class="required-mark" aria-hidden="true">*</span></label>
           <input id="email" name="email" type="email" autocomplete="email" required aria-required="true" aria-describedby="email-error">
           <div id="email-error" class="error-message" aria-live="polite" aria-atomic="true"></div>
         </div>

         <div class="form-field" data-field="phone">
           <label for="phone">Phone number</label>
           <input id="phone" name="phone" type="tel" autocomplete="tel" inputmode="tel" aria-describedby="phone-help phone-error" placeholder="(555) 123-4567">
           <div id="phone-help" class="helper-text">Optional. Use a 10-digit number like (555) 123-4567 or 555-123-4567.</div>
           <div id="phone-error" class="error-message" aria-live="polite" aria-atomic="true"></div>
         </div>

         <div class="actions">
           <button type="submit">Submit request</button>
         </div>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('support-form');
     const fields = {
       fullName: {
         input: document.getElementById('fullName'),
         error: document.getElementById('fullName-error'),
         validate(value) {
           if (!value.trim()) {
             return 'Please enter your full name.';
           }

           return '';
         }
       },
       email: {
         input: document.getElementById('email'),
         error: document.getElementById('email-error'),
         validate(value) {
           if (!value.trim()) {
             return 'Please enter your email address.';
           }

           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
           if (!emailPattern.test(value.trim())) {
             return 'Please enter a valid email address.';
           }

           return '';
         }
       },
       phone: {
         input: document.getElementById('phone'),
         error: document.getElementById('phone-error'),
         validate(value) {
           const trimmed = value.trim();
           if (!trimmed) {
             return '';
           }

           const digits = trimmed.replace(/\D/g, '');
           const phonePattern = /^(?:\d{10}|1\d{10})$/;
           if (!phonePattern.test(digits)) {
             return 'Enter a 10-digit phone number, such as (555) 123-4567.';
           }

           return '';
         }
       }
     };

     function setFieldState(fieldKey, message) {
       const field = fields[fieldKey];
       const fieldWrapper = field.input.closest('.form-field');

       field.error.textContent = message;
       if (message) {
         field.input.setAttribute('aria-invalid', 'true');
       } else {
         field.input.removeAttribute('aria-invalid');
       }
       fieldWrapper.classList.toggle('is-invalid', Boolean(message));
     }

     function validateField(fieldKey) {
       const field = fields[fieldKey];
       const message = field.validate(field.input.value);
       setFieldState(fieldKey, message);
       return !message;
     }

     function validateAll() {
       return Object.keys(fields).every(validateField);
     }

     Object.keys(fields).forEach((fieldKey) => {
       const field = fields[fieldKey];

       field.input.addEventListener('blur', () => {
         validateField(fieldKey);
       });

       field.input.addEventListener('input', () => {
         if (field.error.textContent) {
           validateField(fieldKey);
         } else if (field.input.hasAttribute('aria-invalid')) {
           setFieldState(fieldKey, '');
         }
       });
     });

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       const isValid = validateAll();
       if (!isValid) {
         const firstInvalid = Object.values(fields).find((field) => field.input.getAttribute('aria-invalid') === 'true');
         firstInvalid?.input.focus();
         return;
       }

       form.reset();
       Object.keys(fields).forEach((fieldKey) => setFieldState(fieldKey, ''));
     });
   </script>
 </body>
 </html>
